<?php $e = static fn (mixed $value): string => App\Core\View::e($value); $base = App\Core\Config::url('/campeonatos/' . $championship['slug']); ?>
<section class="portal-page-heading athlete-profile"><?php if ($athlete['photo_path']): ?><img class="portal-athlete-photo portal-athlete-photo-large" src="<?= $e($base . '/atletas/' . $athlete['id'] . '/foto') ?>" alt="Foto de <?= $e($athlete['sporting_name'] ?: $athlete['full_name']) ?>"><?php endif; ?><p class="eyebrow"><?= $e($championship['name']) ?></p><h1><?= $e($athlete['sporting_name'] ?: $athlete['full_name']) ?></h1><p><?= $e($athlete['position_name']) ?> · <a href="<?= $e($base . '/equipes/' . rawurlencode($athlete['team_slug'])) ?>"><?= $e($athlete['team_name']) ?></a></p><?php if ($athlete['preferred_number']): ?><span class="portal-badge">Numero <?= (int) $athlete['preferred_number'] ?></span><?php endif; ?></section>
